class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if not node:
                return 0, float("-inf")
            (lc, lb), (rc, rb) = dfs(node.left), dfs(node.right)
            lc, rc = max(lc, 0), max(rc, 0)
            return node.val + max(lc, rc), max(lb, rb, node.val + lc + rc)
        return dfs(root)[1]

